    if (ocupado) { perguntasPendentes = d; } else { mostrarQuestionario(d); }
    remotoPub('perguntas', { id: Date.now(), dados: d });
    if (turnoDoCelular()) { remotoNotificar('pergunta', (d.perguntas.length > 1 ? d.perguntas.length + ' perguntas: ' : '') + d.perguntas[0].pergunta); }
