          b.className = 'qz-op' + (r.escolhas.indexOf(i) >= 0 ? ' marcada' : '') + (q.multipla ? ' multipla' : '');
          b.innerHTML = '<span class="qz-op-num">' + (i + 1) + '</span><span class="qz-op-txt"><span class="qz-op-rot">' + esc(o.rotulo) + '</span>' + (o.descricao ? '<span class="qz-op-desc">' + esc(o.descricao) + '</span>' : '') + '</span><span class="qz-op-check"></span>';
