          var c = document.createElement('span'); c.className = 'anexo-chip qz-arq-chip'; c.title = a.nome;
          c.innerHTML = '<span class="qz-arq-nome"></span><button type="button" class="qz-arq-x" aria-label="Tirar">&times;</button>';
          c.querySelector('.qz-arq-nome').textContent = a.nome;
          c.querySelector('button').addEventListener('click', function () { r.arquivos.splice(i, 1); desenharLista(); atualizarBotoes(); desenharAbas(); guardar(); });
