    for (i = anexosEnviados.length - 1; i >= 0; i--) { if (anexosEnviados[i].nome.toLowerCase() === nome) { a = anexosEnviados[i]; break; } }
    if (!a) { for (i = anexosEnviados.length - 1; i >= 0; i--) { if (anexosEnviados[i].nome.toLowerCase().indexOf(nome) >= 0) { a = anexosEnviados[i]; break; } } }
    if (!a) { fim({ erro: true, texto: 'ERRO: não achei "' + args.nome + '". Anexos desta conversa: ' + (anexosEnviados.map(function (x) { return x.nome; }).join(', ') || 'nenhum') + '.' }); return; }
    var ext = extDe(a.nome), mime = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', gif: 'image/gif' }[ext];
