      fim({ texto: JSON.stringify({ nome: a.nome, item: a.item, id: a.id, caminho: a.caminho }), imagem: { base64: b.toString('base64'), mime: m }, dataUrl: 'data:' + m + ';base64,' + b.toString('base64') });
