          var vids = achados.filter(function (a) { return /\.(mp4|m4v|webm|mkv|mov)$/i.test(a.n); }).sort(porTam);
          var auds = achados.filter(function (a) { return /\.(m4a|mp3|opus|aac|ogg|webm)$/i.test(a.n) && (!vids[0] || a.p !== vids[0].p); }).sort(porTam);
          if (vids.length) { cb(null, { caminho: vids[0].p, nome: vids[0].n, audio: auds.length ? auds[0].p : null, separado: true }); return; }
