          ultimoErro = 'Não consegui baixar esse link' + (txt ? ' (' + txt.replace(/^ERROR:\s*/i, '').slice(0, 220) + ')' : '') + '. Confira se o post é público ou baixe o vídeo e arraste o arquivo aqui.';
