    for (f = 0; f < 4; f++) { var s4 = 0; for (i = f; i < bt.length; i += 4) { s4 += onL[bt[i]] + 0.5 * (onL[bt[i] + 1] || 0); } if (s4 > mf) { mf = s4; fase = f; } }
