      au.silencios.forEach(function (s) { itens.push({ tipo: 'som', ini: s[0], fim: s[1], gravidade: s[0] < 0.5 || s[1] > dur - 0.5 ? 'ok' : 'media', texto: 'Silêncio de ' + fmt(s[0]) + ' a ' + fmt(s[1]) }); });
      if (au.volume < -30) { itens.push({ tipo: 'som', ini: 0, fim: 0, gravidade: 'media', texto: 'O som está baixo no geral (' + Math.round(au.volume) + ' dB). Reels e Stories ficam em torno de -14 LUFS' }); }
