      var sr = 16000, i, q = 0, pico = 0, est = 0, estEm = null, sil = [], ini = null;
      for (i = 0; i < x.length; i++) { var a = Math.abs(x[i]); q += x[i] * x[i]; if (a > pico) { pico = a; } if (a >= 0.999) { est++; if (estEm === null) { estEm = i / sr; } } }
