  // =====================================================================
  // ATUALIZAÇÃO DO PLUGIN: ao abrir, lê o latest.json publicado. Se houver versão mais nova,
  // a pessoa escolhe baixar e instalar ou continuar com a atual (a não ser que a versão seja obrigatória).
  // =====================================================================
  var atualizacaoHttps = function () { return window.__arcanoFakeAtualizacao || R('https'); };
  function lerJSONUrl(url, cb, saltos) {
    saltos = saltos || 0;
    var req, cb0 = cb, feito = false;
    // sem rede pelo Node: tenta pelo navegador do painel
    cb = function (e, j) {
      if (feito) { return; } feito = true;
      if (!e || window.__arcanoFakeAtualizacao || !/^https:/.test(url) || /^HTTP /.test(e) || e === 'JSON inválido') { cb0(e, j); return; }
      viaNavegador('GET', url + (url.indexOf('?') >= 0 ? '&' : '?') + 't=' + Date.now(), {}, null, 8000, function (e2, st, buf) {
        if (e2 || st !== 200) { cb0(e); return; }
        try { cb0(null, JSON.parse(buf.toString('utf8'))); } catch (x) { cb0('JSON inválido'); }
      });
    };
    try {
      req = atualizacaoHttps().get(url + (url.indexOf('?') >= 0 ? '&' : '?') + 't=' + Date.now(), { headers: { 'Cache-Control': 'no-cache' } }, function (res) {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers && res.headers.location && saltos < 4) { res.resume(); lerJSONUrl(res.headers.location, cb, saltos + 1); return; }
        if (res.statusCode !== 200) { res.resume(); cb('HTTP ' + res.statusCode); return; }
        var partes = [];
        res.on('data', function (d) { partes.push(d); });
        res.on('end', function () { try { cb(null, JSON.parse(R('buffer').Buffer.concat(partes).toString('utf8'))); } catch (e) { cb('JSON inválido'); } });
      });
    } catch (e0) { cb(e0.message); return; }
    req.on('error', function (e) { cb(e.message); });
    req.setTimeout(8000, function () { req.abort(); cb('tempo esgotado'); });
  }

  function verificarAtualizacaoPlugin(cb) {
    var url = (window.ARCANO_APP || {}).atualizacao;
    // no navegador (Arcano Layers) é igual: avisa e instala pelo botão (instalarNoNavegador, cache + sw.js)
    if (!url || !node) { if (cb) { cb(null); } return; }
    lerJSONUrl(url, function (e, info) {
      info = e ? null : infoDoSistema(info);
      if (e || !info || !info.versao || !info.url) { if (cb) { cb(null); } return; }
      if (compararVersao(info.versao, VERSAO) <= 0) { if (cb) { cb(null); } return; }
      var obrigatoria = !!(info.minima && compararVersao(VERSAO, info.minima) < 0);
      mostrarAvisoAtualizacao(info, obrigatoria);
      if (cb) { cb(info); }
    });
  }

  // Mac: o latest.json traz mac: { url, sha256, tamanho } com o .zip da extensão (o .exe é só do Windows)
  function infoDoSistema(info) {
    if (!info || !ehMac()) { return info; }
    var m = info.macos || info.mac;   // "macos" a partir da 1.0.7 ("mac" fazia o Windows antigo achar que era Mac)
    if (!m || !m.url) { return null; }
    var r = {}, k;
    for (k in info) { if (Object.prototype.hasOwnProperty.call(info, k)) { r[k] = info[k]; } }
    r.url = m.url; r.sha256 = m.sha256 || null; r.tamanho = m.tamanho || 0; r.instalarMac = m.instalar || '';
    return r;
  }

  // Mac: troca a pasta da extensão pela do .zip (a versão nova vale na próxima vez que o After abrir). pronto(erro|null)
  function instalarZipMac(zip, pronto) {
    var path = R('path'), ext = pastaExtensao();
    var script = 'set -e; Z="$1"; PAI="$2"; N="$3"; T="$(mktemp -d)"; trap \'rm -rf "$T"\' EXIT; ' +
      '/usr/bin/ditto -x -k "$Z" "$T"; [ -f "$T/com.arcano.motion/CSXS/manifest.xml" ] || { echo "zip incompleto" >&2; exit 3; }; ' +
      'rm -rf "$PAI/$N.novo" "$PAI/$N.velho"; /usr/bin/ditto "$T/com.arcano.motion" "$PAI/$N.novo"; ' +
      'mv "$PAI/$N" "$PAI/$N.velho"; mv "$PAI/$N.novo" "$PAI/$N" || { mv "$PAI/$N.velho" "$PAI/$N"; exit 4; }; rm -rf "$PAI/$N.velho"; ' +
      'if [ "$N" = "com.arcano.design" ] && [ -f "$PAI/$N/ps/manifest.xml" ]; then cp "$PAI/$N/ps/manifest.xml" "$PAI/$N/CSXS/manifest.xml"; [ -f "$PAI/$N/ps/debug" ] && cp "$PAI/$N/ps/debug" "$PAI/$N/.debug"; fi; ' +
      'xattr -dr com.apple.quarantine "$PAI/$N" 2>/dev/null || true';
    rodarAteFim('/bin/bash', ['-c', script, 'arcano', zip, path.dirname(ext), path.basename(ext)], 120000, function (r) {
      pronto(r.codigo === 0 ? null : (String(r.erro || '').trim().slice(0, 200) || ('código ' + r.codigo)));
    });
  }

  // ---- atualização dentro do próprio painel (Windows e Mac), sem fechar o After ----
  // .zip lido em JavaScript puro (sem bash, sem ditto, sem PowerShell): nada de programa externo para falhar
  function lerZip(buf) {
    var zlib = R('zlib'), fim = -1, i;
    for (i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) { if (buf.readUInt32LE(i) === 0x06054b50) { fim = i; break; } }
    if (fim < 0) { throw new Error('zip inválido'); }
    var n = buf.readUInt16LE(fim + 10), pos = buf.readUInt32LE(fim + 16), itens = [];
    for (i = 0; i < n; i++) {
      if (buf.readUInt32LE(pos) !== 0x02014b50) { throw new Error('zip corrompido'); }
      var metodo = buf.readUInt16LE(pos + 10), tamC = buf.readUInt32LE(pos + 20), tamU = buf.readUInt32LE(pos + 24);
      var nl = buf.readUInt16LE(pos + 28), el = buf.readUInt16LE(pos + 30), cl = buf.readUInt16LE(pos + 32), local = buf.readUInt32LE(pos + 42);
      var nome = buf.toString('utf8', pos + 46, pos + 46 + nl);
      pos += 46 + nl + el + cl;
      if (/\/$/.test(nome)) { continue; }
      if (buf.readUInt32LE(local) !== 0x04034b50) { throw new Error('zip corrompido'); }
      var ini = local + 30 + buf.readUInt16LE(local + 26) + buf.readUInt16LE(local + 28), cru = buf.slice(ini, ini + tamC), dados;
      if (metodo === 0) { dados = cru; } else if (metodo === 8) { dados = zlib.inflateRawSync(cru); } else { throw new Error('zip com compressão desconhecida'); }
      if (dados.length !== tamU) { throw new Error('zip corrompido (' + nome + ')'); }
      itens.push({ nome: nome, dados: dados });
    }
    return itens;
  }

  // Os dois painéis moram lado a lado em CEP/extensions: com.arcano.motion (After) e com.arcano.design (Photoshop).
  // O design é uma cópia do motion com o manifesto de ps/manifest.xml (e o .debug de ps/debug).
  function pastasPaineis() {
    var path = R('path'), ext = pastaExtensao(), pai = path.dirname(ext);
    return { motion: ehPS() ? path.join(pai, 'com.arcano.motion') : ext, design: ehPS() ? ext : path.join(pai, 'com.arcano.design') };
  }
  function existePainel(dir) { try { return R('fs').statSync(R('path').join(dir, 'CSXS', 'manifest.xml')).isFile(); } catch (e) { return false; } }
  function photoshopInstalado() {
    if (ehPS()) { return true; }
    try { return !!(window.ArcanoLUT && window.ArcanoLUT.acharPhotoshop && window.ArcanoLUT.acharPhotoshop()); } catch (e) { return false; }
  }
  // arquivo do pacote → onde ele vai em cada painel (null = não vai)
  function destinoNoPainel(rel, tipo) {
    if (tipo === 'ps') {
      if (rel === 'CSXS/manifest.xml' || rel === '.debug') { return null; }   // vêm de ps/manifest.xml e ps/debug
      if (rel === 'ps/manifest.xml') { return 'CSXS/manifest.xml'; }
      if (rel === 'ps/debug') { return '.debug'; }
    }
    return rel;
  }

  // Grava os arquivos novos por cima da extensão instalada: primeiro tudo em ".am-novo", depois troca um por um.
  // Atualiza os DOIS painéis: o After sempre que existir, e o Photoshop se ele já existe ou se o Photoshop está instalado.
  // pronto(erro|null) — o erro é o do painel aberto agora; o outro painel tenta e não atrapalha.
  function instalarZipNoLugar(zip, pronto) {
    var fs = R('fs'), path = R('path'), itens;
    try {
      itens = lerZip(fs.readFileSync(zip)).filter(function (x) { return x.nome.indexOf('com.arcano.motion/') === 0; });
      var manifesto = itens.filter(function (x) { return x.nome === 'com.arcano.motion/CSXS/manifest.xml'; })[0];
      if (!manifesto || !itens.some(function (x) { return x.nome === 'com.arcano.motion/js/app.js'; })) { throw new Error('o arquivo baixado está incompleto'); }
    } catch (e0) { pronto(String(e0 && e0.message || e0)); return; }
    var temPS = itens.some(function (x) { return x.nome === 'com.arcano.motion/ps/manifest.xml'; });
    var p = pastasPaineis(), alvos = [];
    if (!ehPS() || existePainel(p.motion)) { alvos.push({ dir: p.motion, tipo: 'ae', principal: !ehPS() }); }
    if (temPS && (ehPS() || existePainel(p.design) || photoshopInstalado())) { alvos.push({ dir: p.design, tipo: 'ps', principal: ehPS() }); }
    if (ehPS() && !temPS) { pronto('este pacote não traz o painel do Photoshop'); return; }
    var erroPrincipal = null;
    alvos.forEach(function (a) {
      var feitos = [], erro = null;
      try {
        itens.forEach(function (x) {
          var rel = destinoNoPainel(x.nome.slice('com.arcano.motion/'.length), a.tipo);
          if (!rel || /(^|\/)\.\.(\/|$)/.test(rel)) { return; }
          var destino = path.join(a.dir, rel);
          garantirPasta(path.dirname(destino));
          fs.writeFileSync(destino + '.am-novo', x.dados);
          feitos.push(destino);
        });
      } catch (e) {
        feitos.forEach(function (d) { try { fs.unlinkSync(d + '.am-novo'); } catch (e2) {} });
        erro = String(e && e.message || e); feitos = [];
      }
      feitos.forEach(function (d) {
        try { fs.renameSync(d + '.am-novo', d); }
        catch (e3) { try { fs.writeFileSync(d, fs.readFileSync(d + '.am-novo')); fs.unlinkSync(d + '.am-novo'); } catch (e4) { erro = erro || e4.message; } }
      });
      // 1.2.26: o que saiu do pacote some da instalação antiga (depuração remota e o conteúdo que agora vem do servidor)
      if (!erro) { limparArquivosAntigos(a.dir); }
      if (a.principal) { erroPrincipal = erro; }
    });
    pronto(erroPrincipal);
  }

  function limparArquivosAntigos(dir) {
    var fs = R('fs'), path = R('path');
    ['.debug', path.join('ps', 'debug'), path.join('js', 'presets.js')].forEach(function (rel) { try { fs.unlinkSync(path.join(dir, rel)); } catch (e) {} });
    try { apagarPasta(path.join(dir, 'prompt')); } catch (e2) {}
  }
  function apagarPasta(dir) {
    var fs = R('fs'), path = R('path');
    if (!fs.existsSync(dir)) { return; }
    fs.readdirSync(dir).forEach(function (n) {
      var p = path.join(dir, n);
      if (fs.statSync(p).isDirectory()) { apagarPasta(p); } else { try { fs.unlinkSync(p); } catch (e) {} }
    });
    try { fs.rmdirSync(dir); } catch (e2) {}
  }

  // Cria (ou põe em dia) o painel do Photoshop copiando os arquivos deste painel do After.
  // Roda ao abrir o After: quem atualizou pelo painel numa versão antiga (que só gravava o After) ganha o Photoshop também.
  function versaoDoPainel(dir) {
    try { var m = /ExtensionBundleVersion="([^"]+)"/.exec(R('fs').readFileSync(R('path').join(dir, 'CSXS', 'manifest.xml'), 'utf8')); return m ? m[1] : null; } catch (e) { return null; }
  }
  function copiarPasta(origem, destino, tipo, base) {
    var fs = R('fs'), path = R('path');
    base = base || '';
    fs.readdirSync(path.join(origem, base)).forEach(function (n) {
      var relO = base ? base + '/' + n : n, abs = path.join(origem, relO), st = fs.statSync(abs);
      if (/\.am-novo$|\.parcial$/.test(n)) { return; }
      if (st.isDirectory()) { copiarPasta(origem, destino, tipo, relO); return; }
      var rel = destinoNoPainel(relO, tipo);
      if (!rel) { return; }
      var alvo = path.join(destino, rel);
      garantirPasta(path.dirname(alvo));
      fs.writeFileSync(alvo, fs.readFileSync(abs));
    });
  }
  function garantirPainelPhotoshop(cb) {
    cb = cb || function () {};
    if (ehPS() || !node || window.__arcanoSemAutoPS) { cb(null, false); return; }
    try {
      var fs = R('fs'), path = R('path'), ext = pastaExtensao(), p = pastasPaineis();
      if (!fs.existsSync(path.join(ext, 'ps', 'manifest.xml'))) { cb(null, false); return; }
      var existe = existePainel(p.design);
      // só põe em dia o que está ATRÁS desta versão (o Photoshop pode ter se atualizado sozinho para uma mais nova)
      if (existe && compararVersao(versaoDoPainel(p.design) || '0', VERSAO) >= 0) { cb(null, false); return; }
      if (!existe && !photoshopInstalado()) { cb(null, false); return; }
      copiarPasta(ext, p.design, 'ps');
      cb(null, true);
    } catch (e) { cb(String(e && e.message || e), false); }
  }

  // qual .zip usar: "zip" (1.0.7+ publica para todos) ou o do Mac
  function zipDaAtualizacao(info) {
    var z = info && (info.zip || (ehMac() ? (info.macos || info.mac) : null));
    return z && z.url ? z : null;
  }

