    try { garantirPasta(pasta); } catch (e) { cb(null); return; }
    var arq = path.join(pasta, 'rh_previa_' + Date.now() + '_' + Math.floor(Math.random() * 1e5) + '.png');
    jsxCall('previa', ['id:' + layerId, 360, arq], 60000, function (r) {
      if (!r.ok) { cb(null); return; }
      esperarArquivo(arq, 15000, function (existe) {
        if (!existe) { cb(null); return; }
        try { var b = R('fs').readFileSync(arq); R('fs').unlinkSync(arq); cb('data:image/png;base64,' + b.toString('base64')); } catch (e2) { cb(null); }
      });
    });
