        for (j = 0; j < itens.length && !achou; j++) { if (itens[j].pasta && itens[j].nome.toLowerCase().indexOf(alvo) >= 0) { achou = itens[j]; } }
        if (!achou) { cb('Não achei a pasta "' + partes[i] + '". Pastas aqui: ' + itens.filter(function (x) { return x.pasta; }).map(function (x) { return nomeSemNumero(x.nome); }).join(', ')); return; }
        atual = { id: achou.id, nome: achou.nome, categoria: atual.categoria || achou.nome };
