    if (ehWindows()) { pastas.push(path.join(env.WINDIR || 'C:\\Windows', 'Fonts')); if (env.LOCALAPPDATA) { pastas.push(path.join(env.LOCALAPPDATA, 'Microsoft', 'Windows', 'Fonts')); } }
