    var fim = function (e) { if (feito) { return; } feito = true; if (e) { try { fs.unlinkSync(temp); } catch (x) {} } cb(e || null); };
    try { garantirPasta(R('path').dirname(destino)); } catch (e0) { fim('Não consegui criar a pasta: ' + e0.message); return; }
