  function ehAudioDrive(it) { return DRIVE_AUDIO.test(it.nome) || (it.categoria !== undefined ? /AUDIO|SONS?\b/i.test(it.categoria || '') : drivePilha.some(function (p) { return /AUDIO|SONS?\b/i.test(p.nome); })); }
