    itens.forEach(function (x) { if (!x.pasta && /\.abr$/i.test(x.nome)) { var im = imgs[x.nome.replace(/\.[^.]+$/, '').toLowerCase()]; if (im) { x.previa = im.id; usadas[im.id] = 1; } } });
