        corpo.innerHTML = '<div class="rc-espera ok"><span class="rc-espera-ic">✓</span><b>Artes editáveis liberadas!</b><p class="pa-ok-txt"></p></div><div class="modal-acoes"><button class="btn btn-primario" type="button" id="pa-comecar">Ver as artes</button></div>';
