    if ($('btn-anexo')) { $('btn-anexo').addEventListener('click', escolherAnexos); }
    (function () {
      var alvo = $('tela-chat');
      if (!alvo) { return; }
      var temArquivo = function (ev) { var t = ev.dataTransfer && ev.dataTransfer.types; return !!t && Array.prototype.indexOf.call(t, 'Files') >= 0; };
      alvo.addEventListener('dragover', function (ev) { if (!temArquivo(ev) || abaAtual !== 'chat') { return; } ev.preventDefault(); alvo.classList.add('soltando'); });
      alvo.addEventListener('dragleave', function (ev) { if (ev.target === alvo || !alvo.contains(ev.relatedTarget)) { alvo.classList.remove('soltando'); } });
      alvo.addEventListener('drop', function (ev) { alvo.classList.remove('soltando'); if (!temArquivo(ev) || abaAtual !== 'chat') { return; } ev.preventDefault(); adicionarAnexos(ev.dataTransfer.files); });
    })();
